-- Additional MTH206 (49) and MTH208 (41) questions,
-- converted from two real "Solved Problem Sets" exam-prep booklets the user
-- supplied. Unlike prior sources, these were long-form worked proofs/
-- derivations, not ready-made MCQs -- each usable problem (one with a
-- concrete, checkable final answer) was rephrased into a question with the
-- real worked answer plus 3 plausible distractors; pure "state and prove"
-- theorem items with no discrete answer were skipped rather than forced.
--
-- Extraction was unusually careful: several problems were dropped not for
-- being blurry but because independently re-deriving them didn't match the
-- book's own stated answer (a det computation, a Gauss-elimination result
-- that failed when plugged back into its own equations, an LP dual whose
-- transcribed coefficients didn't reconcile) -- those were left out rather
-- than risk enshrining a source error.
--
-- QA before shipping: zero structural errors, zero meta-references, zero
-- middle-dot characters, zero duplicates against the existing banks. Two
-- bare-slash flags in each subject were confirmed to be the established
-- safe exponent pattern ($e^{1/2}$, $(1/3)^{1/3}$), not a real issue.
--
-- MTH206: 598->647, MTH208: 530->571.

insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
   question, options, correct_index, explanation, topic, is_general,
   semester, units)
values
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\lim_{n \to \infty} \frac{5n+4}{n}$.', '["$4$", "$0$", "$5$", "$\\infty$"]'::jsonb, 2, 'Dividing numerator and denominator by $n$ gives $\frac{5n+4}{n} = 5 + \frac{4}{n}$. As $n \to \infty$, the term $\frac{4}{n} \to 0$, so the limit is $5$.', 'Limit of a Rational Sequence', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'What is the behavior of the sequence $x_n = \frac{n^2 - 3n + 9}{3n + 13}$ as $n \to \infty$?', '["It converges to $\\frac{1}{3}$", "It diverges to $+\\infty$", "It converges to $0$", "It converges to $3$"]'::jsonb, 1, 'Dividing numerator and denominator by $n^2$ gives $\frac{1 - \frac{3}{n} + \frac{9}{n^2}}{\frac{3}{n} + \frac{13}{n^2}}$. As $n \to \infty$ the numerator tends to $1$ while the denominator tends to $0^{+}$, so the ratio grows without bound and the sequence diverges to $+\infty$.', 'Divergence of a Rational Sequence', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Using the ratio test, determine the behavior of the series $\sum_{n=1}^{\infty} \frac{(n!)^2}{(2n)!}$.', '["It diverges", "The ratio test is inconclusive", "It converges", "It converges only for even $n$"]'::jsonb, 2, 'With $a_n = \frac{(n!)^2}{(2n)!}$, the ratio $\frac{a_{n+1}}{a_n} = \frac{(n+1)^2}{(2n+2)(2n+1)}$ tends to $0$ as $n \to \infty$, which is less than $1$. By the ratio test, the series converges.', 'Ratio Test for Series Convergence', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the modulus and argument of the complex number $z = -\sqrt{3} + i$.', '["$|z| = 2$, $\\arg z = \\frac{5\\pi}{6}$", "$|z| = 4$, $\\arg z = \\frac{5\\pi}{6}$", "$|z| = 2$, $\\arg z = -\\frac{\\pi}{6}$", "$|z| = 2$, $\\arg z = \\frac{\\pi}{6}$"]'::jsonb, 0, 'The modulus is $|z| = \sqrt{(-\sqrt{3})^2 + 1^2} = \sqrt{4} = 2$. Since $z$ lies in the second quadrant (negative real part, positive imaginary part), the reference angle $\tan^{-1}\left(\frac{1}{\sqrt{3}}\right) = \frac{\pi}{6}$ must be measured from the negative real axis, giving $\arg z = \pi - \frac{\pi}{6} = \frac{5\pi}{6}$.', 'Modulus and Argument of a Complex Number', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the principal (first) cube root of $z = 1 + i$ using De Moivre''s theorem.', '["$2^{\\frac{1}{6}}\\left(\\cos\\frac{\\pi}{4} + i\\sin\\frac{\\pi}{4}\\right)$", "$2^{\\frac{1}{3}}\\left(\\cos\\frac{\\pi}{12} + i\\sin\\frac{\\pi}{12}\\right)$", "$2^{\\frac{1}{6}}\\left(\\cos\\frac{\\pi}{12} + i\\sin\\frac{\\pi}{12}\\right)$", "$2^{\\frac{1}{2}}\\left(\\cos\\frac{\\pi}{12} + i\\sin\\frac{\\pi}{12}\\right)$"]'::jsonb, 2, 'Writing $z = 1+i$ in polar form, $r = |z| = \sqrt{2}$ and $\theta = \arg z = \frac{\pi}{4}$. By De Moivre''s theorem, the cube roots are $z_k = r^{\frac{1}{3}}\left(\cos\frac{\theta + 2k\pi}{3} + i\sin\frac{\theta + 2k\pi}{3}\right)$. Taking $k=0$ gives $z_0 = 2^{\frac{1}{6}}\left(\cos\frac{\pi}{12} + i\sin\frac{\pi}{12}\right)$.', 'Cube Roots via De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate $\lim_{z \to -i} \frac{z^2+1}{z+i}$.', '["$2i$", "$0$", "$-1$", "$-2i$"]'::jsonb, 3, 'Factor the numerator as $z^2+1 = (z+i)(z-i)$, so $\frac{z^2+1}{z+i} = z - i$ for $z \neq -i$. Taking the limit as $z \to -i$ gives $-i - i = -2i$.', 'Limit of a Complex Rational Function', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $f(z) = \frac{z^2-1}{z+i}$, find $f''(i)$.', '["$\\frac{1}{2}$", "$-\\frac{1}{2}$", "$1$", "$2$"]'::jsonb, 0, 'By the quotient rule, $f''(z) = \frac{z^2 + 2iz + 1}{(z+i)^2}$. At $z = i$: the numerator is $i^2 + 2i(i) + 1 = -1 - 2 + 1 = -2$, and the denominator is $(2i)^2 = -4$. Thus $f''(i) = \frac{-2}{-4} = \frac{1}{2}$.', 'Differentiation of a Complex Rational Function', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate $|\sin i|$.', '["$1$", "$\\sinh 1 = \\frac{e - e^{-1}}{2}$", "$0$", "$\\cosh 1$"]'::jsonb, 1, 'Using $\sin(iy) = i\sinh y$, we get $\sin i = i \sinh 1$. Therefore $|\sin i| = |i||\sinh 1| = \sinh 1 = \frac{e - e^{-1}}{2}$.', 'Modulus of a Complex Sine Value', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the principal value of $\log(\sqrt{3} - i)$.', '["$\\ln 2 - i\\frac{\\pi}{6}$", "$\\ln 2 + i\\frac{\\pi}{6}$", "$2 - i\\frac{\\pi}{6}$", "$\\ln 4 - i\\frac{\\pi}{6}$"]'::jsonb, 0, 'For $z = \sqrt{3} - i$, $|z| = \sqrt{3+1} = 2$ and, since the point lies in the fourth quadrant, $\arg z = -\frac{\pi}{6}$. The principal value is $\log z = \ln|z| + i\arg z = \ln 2 - i\frac{\pi}{6}$.', 'Principal Value of the Complex Logarithm', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\lim_{n \to \infty} \frac{6n+8}{n+2}$.', '["$8$", "$3$", "$\\infty$", "$6$"]'::jsonb, 3, 'Dividing numerator and denominator by $n$ gives $\frac{6 + \frac{8}{n}}{1 + \frac{2}{n}}$, which tends to $6$ as $n \to \infty$.', 'Limit of a Rational Sequence', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Let $x_n = \frac{6n+8}{n+2}$, which converges to $6$. Find the smallest $n_0 \in \mathbb{N}$ such that $|x_n - 6| < \frac{1}{10}$ for all $n \geq n_0$.', '["$n_0 = 4$", "$n_0 = 39$", "$n_0 = 40$", "$n_0 = 38$"]'::jsonb, 1, 'We have $|x_n - 6| = \left|\frac{6n+8-6n-12}{n+2}\right| = \frac{4}{n+2}$. Requiring $\frac{4}{n+2} < \frac{1}{10}$ gives $n+2 > 40$, so $n > 38$. The smallest natural number satisfying this is $n_0 = 39$.', 'Epsilon-N Definition of a Sequence Limit', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate $\sum_{n=1}^{\infty} \frac{1}{n(n+1)}$.', '["$\\frac{1}{2}$", "$1$", "$\\infty$", "$0$"]'::jsonb, 1, 'Using partial fractions, $\frac{1}{n(n+1)} = \frac{1}{n} - \frac{1}{n+1}$, so the series telescopes: the partial sum is $1 - \frac{1}{n+1}$. Since $\frac{1}{n+1} \to 0$ as $n \to \infty$, the sum equals $1$.', 'Telescoping Series Sum', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $\mathbf{A} = x^2y\,\mathbf{i} - 2xz\,\mathbf{j} + 2yz\,\mathbf{k}$, find $\operatorname{curl}\mathbf{A}$ at the point $(1,-1,2)$.', '["$6\\mathbf{i} - 5\\mathbf{k}$", "$-6\\mathbf{i} + 5\\mathbf{k}$", "$5\\mathbf{i} - 6\\mathbf{k}$", "$6\\mathbf{i} + 5\\mathbf{k}$"]'::jsonb, 0, 'Computing $\nabla \times \mathbf{A} = \mathbf{i}(2z+2x) - \mathbf{j}(0) + \mathbf{k}(-2z-x^2)$. At $(1,-1,2)$: the $\mathbf{i}$-component is $2(2)+2(1)=6$, the $\mathbf{j}$-component is $0$, and the $\mathbf{k}$-component is $-2(2)-1^2=-5$. So $\operatorname{curl}\mathbf{A} = 6\mathbf{i} - 5\mathbf{k}$.', 'Curl of a Vector Field', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Solve $z^3 = 1$ for all complex roots $z$.', '["$z = 1$ only", "$z = 1,\\ \\frac{1}{2}+\\frac{\\sqrt{3}}{2}i,\\ \\frac{1}{2}-\\frac{\\sqrt{3}}{2}i$", "$z = 1,\\ -1+\\frac{\\sqrt{3}}{2}i,\\ -1-\\frac{\\sqrt{3}}{2}i$", "$z = 1,\\ -\\frac{1}{2}+\\frac{\\sqrt{3}}{2}i,\\ -\\frac{1}{2}-\\frac{\\sqrt{3}}{2}i$"]'::jsonb, 3, 'Writing $z^3 - 1 = 0$ with $r = |z| = 1$ and $\theta = \arg z = 0$, the roots are $z_k = \cos\frac{2k\pi}{3} + i\sin\frac{2k\pi}{3}$ for $k=0,1,2$. This gives $z_0 = 1$, $z_1 = -\frac{1}{2}+\frac{\sqrt{3}}{2}i$, and $z_2 = -\frac{1}{2}-\frac{\sqrt{3}}{2}i$, the familiar cube roots of unity.', 'Roots of Unity via De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the principal square root of $z$ where $z^2 = 1 - i$.', '["$2^{\\frac{1}{4}}\\left[\\cos\\left(-\\frac{\\pi}{8}\\right) + i\\sin\\left(-\\frac{\\pi}{8}\\right)\\right]$", "$2^{\\frac{1}{2}}\\left[\\cos\\left(-\\frac{\\pi}{8}\\right) + i\\sin\\left(-\\frac{\\pi}{8}\\right)\\right]$", "$2^{\\frac{1}{4}}\\left[\\cos\\left(\\frac{\\pi}{8}\\right) + i\\sin\\left(\\frac{\\pi}{8}\\right)\\right]$", "$2^{\\frac{1}{4}}\\left[\\cos\\left(-\\frac{\\pi}{4}\\right) + i\\sin\\left(-\\frac{\\pi}{4}\\right)\\right]$"]'::jsonb, 0, 'Writing $1-i$ in polar form: $r = |1-i| = \sqrt{2}$ and $\theta = \arg(1-i) = -\frac{\pi}{4}$. The principal square root is $r^{\frac{1}{2}}\left(\cos\frac{\theta}{2}+i\sin\frac{\theta}{2}\right) = 2^{\frac{1}{4}}\left[\cos\left(-\frac{\pi}{8}\right)+i\sin\left(-\frac{\pi}{8}\right)\right]$.', 'Square Roots via De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Simplify $\frac{(1+i)^{200}}{(1-i)^{160}}$.', '["$2^{20}$", "$2^{40}$", "$2^{10}$", "$-2^{20}$"]'::jsonb, 0, 'Writing $1+i = \sqrt{2}\,e^{i\pi/4}$ and $1-i = \sqrt{2}\,e^{-i\pi/4}$, we get $\frac{(1+i)^{200}}{(1-i)^{160}} = \frac{2^{100}e^{i50\pi}}{2^{80}e^{-i40\pi}} = 2^{20}e^{i90\pi}$. Since $90\pi$ is an even multiple of $2\pi$ shifted appropriately, $e^{i90\pi} = 1$, so the result is $2^{20}$.', 'Powers of Complex Numbers via Polar Form', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate $\lim_{n \to \infty} \sqrt{n}\left(\sqrt{n+1} - \sqrt{n}\right)$.', '["$0$", "$1$", "$\\infty$", "$\\frac{1}{2}$"]'::jsonb, 3, 'Rationalizing, $\sqrt{n}(\sqrt{n+1}-\sqrt{n}) = \frac{n}{\sqrt{n+1}+\sqrt{n}} = \frac{1}{\sqrt{1+\frac{1}{n}}+1}$. As $n \to \infty$, this tends to $\frac{1}{1+1} = \frac{1}{2}$.', 'Limit Involving Square Roots', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'A sequence $x_n$ satisfies $0 \leq x_n < \frac{2}{n}$ for all $n$. What is $\lim_{n \to \infty} x_n$?', '["$2$", "$\\frac{1}{2}$", "It does not exist", "$0$"]'::jsonb, 3, 'Since $\lim_{n \to \infty} 0 = 0$ and $\lim_{n \to \infty} \frac{2}{n} = 0$, the sandwich (squeeze) theorem forces $\lim_{n \to \infty} x_n = 0$.', 'Squeeze Theorem for Sequences', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Test the series $\sum_{n=1}^{\infty} \frac{1}{\sqrt{n}}$ for convergence using the $p$-series test.', '["It converges since $p = \\frac{1}{2} < 1$", "It diverges since $p = \\frac{1}{2} \\leq 1$", "It converges since $p = 2$", "It diverges since $p = 2$"]'::jsonb, 1, 'The series $\sum \frac{1}{\sqrt{n}} = \sum \frac{1}{n^{1/2}}$ is a $p$-series with $p = \frac{1}{2}$. Since $p$-series converge only when $p > 1$, and here $p = \frac{1}{2} \leq 1$, the series diverges.', 'p-Series Test for Convergence', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Test the series $\sum_{n=1}^{\infty} \frac{n!}{(2n)!}$ for convergence using the ratio test.', '["It diverges", "The ratio test fails", "It converges", "It converges only conditionally"]'::jsonb, 2, 'With $a_n = \frac{n!}{(2n)!}$, the ratio $\frac{a_{n+1}}{a_n} = \frac{n+1}{(2n+2)(2n+1)}$ tends to $0$ as $n \to \infty$. Since this limit is less than $1$, the series converges by the ratio test.', 'Ratio Test for Series Convergence', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $\mathbf{A} = x^2y\,\mathbf{i} - 2xz\,\mathbf{j} + 2y\,\mathbf{k}$, find $\operatorname{curl}(\operatorname{curl}\mathbf{A})$ at the point $(1,0,1)$.', '["$2\\mathbf{i}$", "$2\\mathbf{j}$", "$-2\\mathbf{j}$", "$2\\mathbf{k}$"]'::jsonb, 1, 'First, $\operatorname{curl}\mathbf{A} = (2+2x)\mathbf{i} + (-2z-x^2)\mathbf{k}$. Taking the curl of this result gives $\nabla \times \nabla \times \mathbf{A} = 2x\,\mathbf{j}$. At $(1,0,1)$, this evaluates to $2(1)\mathbf{j} = 2\mathbf{j}$.', 'Curl of a Curl (Vector Identity)', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $a_n = \frac{n!}{n^n}$, find $\lim_{n \to \infty} \frac{a_{n+1}}{a_n}$ and state whether $\sum a_n$ converges.', '["Limit is $1$; the series diverges", "Limit is $e$; the series diverges", "Limit is $\\frac{1}{e}$; the series converges", "Limit is $0$; the series converges"]'::jsonb, 2, 'We have $\frac{a_{n+1}}{a_n} = \left(\frac{n}{n+1}\right)^n = \frac{1}{\left(1+\frac{1}{n}\right)^n}$. As $n \to \infty$, $\left(1+\frac{1}{n}\right)^n \to e$, so the ratio tends to $\frac{1}{e} \approx 0.368 < 1$. By the ratio test, $\sum \frac{n!}{n^n}$ converges.', 'Ratio Test with Euler''s Number', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find all real numbers $x$ satisfying $|x| + |x+3| \leq 5$.', '["$-3 \\leq x \\leq 1$", "$-4 \\leq x \\leq 1$", "$-5 \\leq x \\leq 2$", "$-4 \\leq x \\leq 2$"]'::jsonb, 1, 'For $x \geq 0$: $2x+3 \leq 5 \Rightarrow x \leq 1$. For $-3 \leq x \leq 0$: the expression simplifies to the constant $3 \leq 5$, always true. For $x < -3$: $-2x - 3 \leq 5 \Rightarrow x \geq -4$. Combining all three cases gives $-4 \leq x \leq 1$.', 'Solving Absolute Value Inequalities', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the principal square root of $i$.', '["$\\frac{1+i}{\\sqrt{2}}$", "$1+i$", "$\\frac{\\sqrt{2}}{2}(1-i)$", "$i$"]'::jsonb, 0, 'Writing $i$ in polar form, $r=1$, $\theta = \frac{\pi}{2}$. The principal square root is $\cos\frac{\pi}{4} + i\sin\frac{\pi}{4} = \frac{\sqrt{2}}{2} + i\frac{\sqrt{2}}{2} = \frac{1+i}{\sqrt{2}}$.', 'Square Root of a Complex Number', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the modulus of the complex number $3+4i$.', '["$7$", "$\\sqrt{7}$", "$\\sqrt{2}$", "$5$"]'::jsonb, 3, 'The modulus is $|3+4i| = \sqrt{3^2+4^2} = \sqrt{9+16} = \sqrt{25} = 5$.', 'Modulus of a Complex Number', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $z^{10}$ where $z = \sqrt{3} + i$.', '["$1024(1-i\\sqrt{3})$", "$512(1+i\\sqrt{3})$", "$512(1-i\\sqrt{3})$", "$256(1-i\\sqrt{3})$"]'::jsonb, 2, 'Writing $z$ in polar form, $r = |z| = 2$ and $\theta = \arg z = \frac{\pi}{6}$. By De Moivre''s theorem, $z^{10} = 2^{10}\left(\cos\frac{10\pi}{6}+i\sin\frac{10\pi}{6}\right) = 1024\left(\frac{1}{2} - i\frac{\sqrt{3}}{2}\right) = 512(1-i\sqrt{3})$.', 'Powers via De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the principal value of $\log(i)$.', '["$i\\pi$", "$i\\frac{\\pi}{2}$", "$0$", "$-i\\frac{\\pi}{2}$"]'::jsonb, 1, 'Since $|i| = 1$ and the principal argument of $i$ is $\frac{\pi}{2}$, we have $\log i = \ln|i| + i\arg i = \ln 1 + i\frac{\pi}{2} = i\frac{\pi}{2}$.', 'Principal Value of the Complex Logarithm', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the infimum and supremum of the open interval $A = (-4, 9)$.', '["Infimum $= -4$, supremum $= 9$", "Infimum $= 0$, supremum $= 9$", "Infimum $= -4$, supremum $= \\infty$", "No infimum or supremum exists"]'::jsonb, 0, 'Every element of $A$ is bounded below by $-4$ and above by $9$, and no larger lower bound or smaller upper bound works since points arbitrarily close to $-4$ and $9$ lie in $A$. So $\inf A = -4$ and $\sup A = 9$ (neither is attained, since the interval is open).', 'Infimum and Supremum of a Set', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the infimum and supremum of $B = \left\{1, \frac{1}{2}, \frac{1}{3}, \dots\right\}$.', '["Infimum $= \\frac{1}{2}$, supremum $= 1$", "Infimum $= 0$, supremum $= 1$", "Infimum $= 0$, supremum $= \\infty$", "Infimum and supremum both equal $0$"]'::jsonb, 1, 'The terms $\frac{1}{n}$ decrease toward $0$ but never reach it, so $\inf B = 0$ (not attained). The largest term is the first one, $n=1$, giving $\sup B = 1$ (attained).', 'Infimum and Supremum of a Set', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Solve $(z+1)^3 = 64i$ for the root corresponding to $k=0$ in De Moivre''s formula.', '["$z = 2\\sqrt{3} - 1 + 2i$", "$z = -2\\sqrt{3} - 1 + 2i$", "$z = -1 - 4i$", "$z = 2\\sqrt{3} + 1 + 2i$"]'::jsonb, 0, 'Writing $64i$ in polar form, $r = 64$, $\theta = \frac{\pi}{2}$. The cube roots satisfy $z+1 = 4\left(\cos\frac{\theta+2k\pi}{3}+i\sin\frac{\theta+2k\pi}{3}\right)$. For $k=0$, the angle is $\frac{\pi}{6}$, giving $z+1 = 4\left(\frac{\sqrt{3}}{2}+i\frac{1}{2}\right) = 2\sqrt{3}+2i$, so $z = 2\sqrt{3}-1+2i$.', 'Solving Cubic Equations via De Moivre''s Theorem', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the locus of points $z = x+iy$ satisfying $|z+1| = |z+i|$.', '["The circle $x^2+y^2=1$", "The line $x=-y$", "The line $y=0$", "The line $x=y$"]'::jsonb, 3, 'Squaring both sides, $(x+1)^2+y^2 = x^2+(y+1)^2$. Expanding gives $2x+1 = 2y+1$, which simplifies to $x=y$. This is the perpendicular bisector of the segment joining $-1$ and $-i$, as expected since both points are equidistant from the line $y=x$.', 'Locus of a Complex Equation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find the harmonic conjugate $v(x,y)$ of $u(x,y) = e^x \sin y$ (taking the arbitrary constant to be zero).', '["$v = e^x \\sin y$", "$v = -e^x \\cos y$", "$v = e^x \\cos y$", "$v = -e^x \\sin y$"]'::jsonb, 1, 'Since $u_x = e^x\sin y$ and $u_y = e^x\cos y$, the Cauchy-Riemann equations require $v_y = u_x = e^x\sin y$, so integrating with respect to $y$ gives $v = -e^x\cos y + f(x)$. Differentiating with respect to $x$ and matching against $v_x=-u_y$ shows $f''(x)=0$, so $v = -e^x\cos y$.', 'Harmonic Conjugate via Cauchy-Riemann Equations', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $f(z) = z^2 + 4z + 1$ with $z = x+iy$, find $\operatorname{Re} f(z)$ and $\operatorname{Im} f(z)$.', '["$\\operatorname{Re} f = x^2-y^2+4x+1$, $\\operatorname{Im} f = 2y(x+2)$", "$\\operatorname{Re} f = x^2+y^2+4x+1$, $\\operatorname{Im} f = 2xy$", "$\\operatorname{Re} f = x^2-y^2+4x+1$, $\\operatorname{Im} f = 2xy$", "$\\operatorname{Re} f = x^2-y^2+1$, $\\operatorname{Im} f = 2y(x+2)$"]'::jsonb, 0, 'Expanding, $z^2 = x^2-y^2+2ixy$ and $4z=4x+4iy$, so $f(z) = (x^2-y^2+4x+1) + i(2xy+4y)$. Thus $\operatorname{Re} f(z) = x^2-y^2+4x+1$ and $\operatorname{Im} f(z) = 2xy+4y = 2y(x+2)$.', 'Real and Imaginary Parts of a Complex Function', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Test the series $\sum_{n=1}^{\infty} \frac{n}{n^2+1}$ for convergence.', '["It converges absolutely", "It converges conditionally", "It diverges", "It converges to $0$"]'::jsonb, 2, 'For large $n$, $\frac{n}{n^2+1} \sim \frac{1}{n}$. Comparing with the harmonic series $\sum \frac{1}{n}$ via the limit comparison test, $\lim_{n\to\infty} \frac{n/(n^2+1)}{1/n} = \lim_{n\to\infty}\frac{n^2}{n^2+1} = 1$, a finite nonzero value. Since $\sum \frac{1}{n}$ diverges, so does $\sum \frac{n}{n^2+1}$.', 'Limit Comparison Test for Series', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Test the series $\sum_{n=2}^{\infty} \frac{1}{n(n-1)}$ for convergence.', '["It diverges", "It converges", "It oscillates", "The test is inconclusive"]'::jsonb, 1, 'For large $n$, $\frac{1}{n(n-1)} \sim \frac{1}{n^2}$. Comparing with $\sum \frac{1}{n^2}$, a convergent $p$-series with $p=2$, via the limit comparison test gives a finite nonzero ratio limit of $1$. Since $\sum \frac{1}{n^2}$ converges, so does $\sum \frac{1}{n(n-1)}$ (in fact it telescopes to the value $1$).', 'Limit Comparison Test for Series', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Test the series $\sum_{n=1}^{\infty} \frac{n!}{(n+1)!}$ for convergence.', '["It converges to $1$", "It converges to $0$", "It diverges", "It converges to $\\frac{1}{2}$"]'::jsonb, 2, 'Since $\frac{n!}{(n+1)!} = \frac{1}{n+1}$, the series is $\sum \frac{1}{n+1}$, which is essentially the harmonic series shifted by one term. Comparing $a_n=\frac{1}{n+1}$ with $b_n=\frac{1}{n}$ via the limit comparison test gives a ratio limit of $1$, and since $\sum \frac{1}{n}$ diverges, so does $\sum \frac{n!}{(n+1)!}$.', 'Limit Comparison Test for Series', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate $e^{\frac{2+\pi i}{4}}$.', '["$\\frac{\\sqrt{2}}{2}\\sqrt{e}\\,(1-i)$", "$\\sqrt{e}\\,i$", "$\\frac{\\sqrt{2}}{2}\\sqrt{e}\\,(1+i)$", "$\\frac{\\sqrt{2}}{2}(1+i)$"]'::jsonb, 2, 'Write the exponent as $\frac{2+\pi i}{4} = \frac{1}{2} + \frac{\pi}{4}i$, so $e^{\frac{2+\pi i}{4}} = e^{1/2}\left(\cos\frac{\pi}{4} + i\sin\frac{\pi}{4}\right)$. Since $\cos\frac{\pi}{4}=\sin\frac{\pi}{4}=\frac{\sqrt{2}}{2}$, this simplifies to $\frac{\sqrt{2}}{2}\sqrt{e}\,(1+i)$.', 'Evaluating a Complex Exponential', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate $\sinh\left(\frac{2+\pi i}{2}\right)$.', '["$\\cosh 1$", "$-i\\cosh 1$", "$i\\sinh 1$", "$i\\cosh 1$"]'::jsonb, 3, 'Rewrite $\frac{2+\pi i}{2} = 1 + \frac{\pi}{2}i$, then expand using $\sinh(a+bi) = \sinh a \cos b + i\cosh a \sin b$. This gives $\sinh 1 \cos\frac{\pi}{2} + i\cosh 1 \sin\frac{\pi}{2}$. Since $\cos\frac{\pi}{2}=0$ and $\sin\frac{\pi}{2}=1$, the result reduces to $i\cosh 1$.', 'Evaluating the Complex Hyperbolic Sine', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\lim_{n \to \infty} \frac{7n-19}{3n+7}$.', '["$1$", "$\\frac{19}{3}$", "$-\\frac{19}{7}$", "$\\frac{7}{3}$"]'::jsonb, 3, 'For a rational sequence, the limit as $n \to \infty$ is the ratio of the leading coefficients of $n$ in the numerator and denominator, since the constant terms become negligible. Here that ratio is $\frac{7}{3}$, and this can be confirmed rigorously with an $\epsilon$-$\delta$ argument.', 'Limit of a Rational Sequence', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate $\cos i$.', '["$1$", "$i\\sinh 1$", "$\\sinh 1$", "$\\cosh 1$"]'::jsonb, 3, 'Using the identity $\cos(iz) = \cosh z$ with $z=1$, we get $\cos i = \cosh 1 = \frac{e+e^{-1}}{2}$. This is a real number, not equal to $e^{i\pi}$.', 'Cosine of a Purely Imaginary Number', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $z = x + iy \neq 0$ with $x, y$ real, find the multiplicative inverse $z^{-1}$ in terms of $x$ and $y$.', '["$\\frac{x}{x^2+y^2} + i\\frac{y}{x^2+y^2}$", "$x - iy$", "$\\frac{x}{x^2+y^2} - i\\frac{y}{x^2+y^2}$", "$\\frac{x^2+y^2}{x} - i\\frac{x^2+y^2}{y}$"]'::jsonb, 2, 'Writing $z^{-1} = u+iv$ and solving $zz^{-1}=1$ gives the system $xu-yv=1$ and $yu+xv=0$. Solving this system by Cramer''s rule yields $u=\frac{x}{x^2+y^2}$ and $v=\frac{-y}{x^2+y^2}$, so $z^{-1} = \frac{x}{x^2+y^2} - i\frac{y}{x^2+y^2}$.', 'Multiplicative Inverse of a Complex Number', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find all $x \in \mathbb{R}$ such that $|2x-2| \geq |2x+4|$.', '["$\\left[-\\frac{1}{2}, \\infty\\right)$", "$\\left(-\\infty, -3\\right]$", "$\\left(-\\infty, \\frac{1}{2}\\right]$", "$\\left(-\\infty, -\\frac{1}{2}\\right]$"]'::jsonb, 3, 'Squaring both sides (valid since both sides are nonnegative) gives $(2x-2)^2 \geq (2x+4)^2$, which expands to $4x^2-8x+4 \geq 4x^2+16x+16$. This simplifies to $-24x \geq 12$, so $x \leq -\frac{1}{2}$, giving the solution set $\left(-\infty, -\frac{1}{2}\right]$.', 'Solving an Absolute Value Inequality', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Determine whether $f(z) = \frac{z+2i}{z^2+4}$ is continuous at $z_0 = -2i$.', '["Continuous, since $f(z_0) = 0$", "Not continuous; $f(z_0)$ is an indeterminate $\\frac{0}{0}$ form", "Continuous everywhere since $z^2+4$ has no real roots", "Not continuous; $f(z_0)$ is undefined because the denominator is nonzero"]'::jsonb, 1, 'Substituting $z_0=-2i$ gives $f(-2i) = \frac{-2i+2i}{(-2i)^2+4} = \frac{0}{-4+4} = \frac{0}{0}$, which is indeterminate. Since $f(z_0)$ cannot be assigned a well-defined value this way, $f$ fails to be continuous at $z_0=-2i$.', 'Continuity of a Complex Rational Function', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If a complex number $z$ satisfies $z^3+3z^2+5z+10=0$, what must be true about $|z|$?', '["$|z| = 1$ exactly", "$|z| \\leq 1$", "$|z| < 1$", "$|z| \\geq 1$"]'::jsonb, 3, 'Suppose for contradiction that $|z| \leq 1$. Then from the equation, $10 = |z^3+3z^2+5z| \leq |z|^3+3|z|^2+5|z| \leq 1+3+5=9$, giving the absurd statement $10 \leq 9$. This contradiction shows the assumption $|z|\leq 1$ is false, so $|z| \geq 1$ for any such $z$.', 'Modulus Bound from a Polynomial Equation', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $\lim_{n \to \infty} \frac{2n+1}{3n-2}$.', '["$\\frac{3}{2}$", "$\\frac{1}{3}$", "$-\\frac{2}{3}$", "$\\frac{2}{3}$"]'::jsonb, 3, 'For large $n$, the behavior of $\frac{2n+1}{3n-2}$ is governed by the ratio of the coefficients of $n$, since the constant terms $1$ and $-2$ become insignificant. Dividing numerator and denominator by $n$ confirms the limit is $\frac{2}{3}$.', 'Limit of a Rational Sequence', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Does the series $\sum_{n=1}^{\infty} \frac{1}{n \cdot 3^n}$ converge or diverge?', '["Diverges, since the ratio test gives a limit of $3 > 1$", "Converges, since it is a geometric series with ratio $3$", "Diverges by the divergence test since the terms do not tend to $0$", "Converges, since the ratio test gives a limit of $\\frac{1}{3} < 1$"]'::jsonb, 3, 'Let $a_n = \frac{1}{n \cdot 3^n}$. Then $\left|\frac{a_{n+1}}{a_n}\right| = \frac{n}{3(n+1)} \to \frac{1}{3}$ as $n \to \infty$. Since $\frac{1}{3} < 1$, the ratio test confirms that $\sum_{n=1}^{\infty} \frac{1}{n \cdot 3^n}$ converges.', 'Ratio Test for Series Convergence', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Evaluate $\sum_{n=1}^{\infty} \frac{1}{n(n+2)}$.', '["$\\frac{1}{2}$", "$1$", "$\\frac{3}{4}$", "$\\frac{1}{4}$"]'::jsonb, 2, 'Using partial fractions, $\frac{1}{n(n+2)} = \frac{1}{2}\left(\frac{1}{n} - \frac{1}{n+2}\right)$. Writing out the sum, all but the first two terms cancel telescopically, leaving $\frac{1}{2}\left(1+\frac{1}{2}\right) = \frac{3}{4}$.', 'Telescoping Series Sum', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $f(x,y,z) = x^3+y^3+z^3$, find the directional derivative of $f$ at the point $(1,-1,2)$ in the direction of the vector $i+j+k$.', '["$-4\\sqrt{3}$", "$\\frac{13\\sqrt{3}}{3}$", "$2\\sqrt{3}$", "$4\\sqrt{3}$"]'::jsonb, 3, 'The gradient is $\nabla f = 3x^2 i + 3y^2 j + 3z^2 k$, and the unit vector in the direction of $i+j+k$ is $\frac{1}{\sqrt{3}}(i+j+k)$. The directional derivative is $\nabla f \cdot \frac{i+j+k}{\sqrt{3}} = \sqrt{3}(x^2+y^2+z^2)$. At $(1,-1,2)$, this gives $\sqrt{3}(1+1+4) = 4\sqrt{3}$.', 'Directional Derivative of a Scalar Field', false, 'second', 2),
  ('mth-206-advanced-mathematics-vi', 'MTH 206: Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Let $\vec{a} = x^2 i + 3y^2 j + z k$ and $\vec{b} = x^2 i - 3y j + z k$. Evaluate $\frac{\partial^2}{\partial x \partial y}(\vec{b} \times \vec{a})$ at the point $(1,0,2)$.', '["$3k$", "$-6k$", "$12k$", "$6k$"]'::jsonb, 3, 'Computing the cross product gives $\vec{b}\times\vec{a} = -(3yz+3y^2z)i + (3x^2y^2+3x^2y)k$. Differentiating with respect to $y$ gives $-(3z+6yz)i + (6x^2y+3x^2)k$, and differentiating again with respect to $x$ gives $(12xy+6x)k$. At $(1,0,2)$, this evaluates to $(12(1)(0)+6(1))k = 6k$.', 'Second Mixed Partial of a Vector Cross Product', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Using the graphical method, find the optimal solution and maximum value of $z = 3x_1 + 2x_2$ subject to $5x_1 - x_2 \leq 30$, $x_1 + x_2 \leq 18$, $x_1, x_2 \geq 0$.', '["$(x_1, x_2) = (6, 0)$, $z = 18$", "$(x_1, x_2) = (0, 18)$, $z = 36$", "$(x_1, x_2) = (8, 10)$, $z = 44$", "$(x_1, x_2) = (8, 10)$, $z = 40$"]'::jsonb, 2, 'The feasible region has corner points $O(0,0)$, $A(6,0)$, $B(8,10)$, and $C(0,18)$, found by intersecting the boundary lines $5x_1-x_2=30$ and $x_1+x_2=18$ (which meet at $B$). Evaluating $z=3x_1+2x_2$ at each corner gives $0, 18, 44,$ and $36$ respectively, so the maximum occurs at $B(8,10)$ with $z=3(8)+2(10)=44$.', 'Graphical Method for LP', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For what value of the constant $k$ does the system $x - y = 3$, $2x - 2y = k$ have infinitely many solutions?', '["$k = 3$", "$k = 6$", "$k = -6$", "$k \\neq 6$"]'::jsonb, 1, 'Writing the augmented matrix $\begin{pmatrix} 1 & -1 & : & 3 \\ 2 & -2 & : & k \end{pmatrix}$ and applying $R_2 \to -2R_1+R_2$ gives $\begin{pmatrix} 1 & -1 & : & 3 \\ 0 & 0 & : & -6+k \end{pmatrix}$. The second row becomes $0 = -6+k$, which is only consistent (giving infinitely many solutions since a free variable remains) when $k=6$. Any $k \neq 6$ instead makes the system inconsistent (no solution).', 'System of Linear Equations with a Parameter', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For what value(s) of $\lambda$ does the system $(\lambda-3)x + y = 0$, $x + (\lambda-3)y = 0$ have non-trivial solutions?', '["$\\lambda = 3$ or $\\lambda = -3$", "$\\lambda = 6$ or $\\lambda = 8$", "$\\lambda = 2$ or $\\lambda = -4$", "$\\lambda = 2$ or $\\lambda = 4$"]'::jsonb, 3, 'A homogeneous system has non-trivial solutions exactly when the coefficient determinant vanishes: $\begin{vmatrix} \lambda-3 & 1 \\ 1 & \lambda-3 \end{vmatrix} = (\lambda-3)^2 - 1 = 0$. Expanding gives $\lambda^2 - 6\lambda + 8 = 0$, which factors as $(\lambda-2)(\lambda-4)=0$, so $\lambda = 2$ or $\lambda = 4$.', 'Non-Trivial Solutions of a Homogeneous System', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'By checking for a sign change in $f(x) = x^2 - \ln x - 12$, which interval contains a root of $x^2 - \ln x - 12 = 0$?', '["$[1, 2]$", "$[2, 3]$", "$[3, 4]$", "$[4, 5]$"]'::jsonb, 2, 'Evaluating $f(x) = x^2 - \ln x - 12$ at $x=3$ gives $9 - \ln 3 - 12 = -3 - 1.099 = -4.099 < 0$, and at $x=4$ gives $16 - \ln 4 - 12 = 4 - 1.386 = 2.614 > 0$. Since $f$ changes sign between $x=3$ and $x=4$, the interval $[3,4]$ contains a root.', 'Locating an Interval Containing a Root', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'The augmented matrix of a system of linear equations in 4 unknowns row-reduces to $\begin{pmatrix} 1 & -1 & 2 & -1 & : & -1 \\ 0 & 3 & -6 & 0 & : & 0 \\ 0 & 0 & 0 & 0 & : & -2 \\ 0 & 0 & 0 & 0 & : & 0 \end{pmatrix}$. What are the rank of the coefficient matrix, the rank of the augmented matrix, and the resulting solution type?', '["Rank of coefficient matrix $= 3$, rank of augmented matrix $= 3$, unique solution", "Rank of coefficient matrix $= 2$, rank of augmented matrix $= 2$, infinitely many solutions", "Rank of coefficient matrix $= 2$, rank of augmented matrix $= 3$, no solution", "Rank of coefficient matrix $= 2$, rank of augmented matrix $= 3$, infinitely many solutions"]'::jsonb, 2, 'In the row-echelon form, only the first two rows of the coefficient part contain non-zero entries, so the rank of the coefficient matrix is $2$. However, the third row reads $0 = -2$, a non-zero entry in the augmented column with an all-zero coefficient row, so the rank of the augmented matrix is $3$. Since the rank of the augmented matrix exceeds the rank of the coefficient matrix, the system has no solution.', 'Rank of a Matrix and Solution Type', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Which of the following correctly states the Newton-Raphson iteration formula for approximating a root of $f(x) = 0$?', '["$x_{n+1} = x_n - \\dfrac{f''(x_n)}{f(x_n)}$", "$x_{n+1} = x_n + \\dfrac{f(x_n)}{f''(x_n)}$", "$x_{n+1} = x_n - \\dfrac{f(x_n)}{f''(x_n)}$", "$x_{n+1} = x_n - \\dfrac{f(x_n)}{f''''(x_n)}$"]'::jsonb, 2, 'The Newton-Raphson method approximates a root by taking the tangent line to $f$ at the current estimate $x_n$ and finding where that tangent crosses the $x$-axis. This gives the iterative formula $x_{n+1} = x_n - \dfrac{f(x_n)}{f''(x_n)}$, starting from an initial guess $x_0$.', 'Newton-Raphson Iteration Scheme', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'A function $f$ passes through the points $(0,-1)$, $(1,1)$, $(2,1)$, and $(3,2)$. Using a forward difference table, find the third forward difference $\Delta^3 f(0)$.', '["$\\Delta^3 f(0) = -2$", "$\\Delta^3 f(0) = 0$", "$\\Delta^3 f(0) = 1$", "$\\Delta^3 f(0) = 3$"]'::jsonb, 3, 'The first differences are $\Delta y_0 = 1-(-1)=2$, $\Delta y_1 = 1-1=0$, $\Delta y_2 = 2-1=1$. The second differences are $\Delta^2 y_0 = 0-2=-2$ and $\Delta^2 y_1 = 1-0=1$. The third difference is then $\Delta^3 y_0 = 1-(-2) = 3$.', 'Forward Difference Table', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'A furniture company makes chairs and tables using machines A and B. A chair needs 1 hour on A and 3 hours on B; a table needs 2 hours on A and 1 hour on B. Machine A has 10 hours available per day and machine B has 15 hours. Profit is N200 per chair and N300 per table. What is the optimal number of chairs and tables to produce, and the resulting maximum profit?', '["4 chairs, 3 tables, profit N1700", "5 chairs, 0 tables, profit N1000", "0 chairs, 5 tables, profit N1500", "4 chairs, 3 tables, profit N1400"]'::jsonb, 0, 'Letting $x$ be the number of chairs and $y$ the number of tables, the LP model is maximize $Z=200x+300y$ subject to $x+2y \leq 10$, $3x+y \leq 15$, $x,y \geq 0$. Solving the binding constraints $x+2y=10$ and $3x+y=15$ simultaneously gives $x=4$, $y=3$, which beats the other corner points $O(0,0)$, $A(5,0)$, and $C(0,5)$. The maximum profit is $Z=200(4)+300(3)=800+900=1700$.', 'Formulating and Solving an LP Model', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Let $a = \tan x$, $b = \sin y$, $c = \cos z$. Solve the linear system $a - 2b = 2$, $a - b + c = 2$, $b - c = -1$, then use the results to find $x$, $y$, and $z$ in the given intervals.', '["$x = \\dfrac{\\pi}{4}$, $y = \\dfrac{7\\pi}{6}$, $z = \\dfrac{\\pi}{3}$", "$x = \\dfrac{\\pi}{3}$, $y = \\dfrac{7\\pi}{6}$, $z = \\dfrac{\\pi}{4}$", "$x = \\dfrac{\\pi}{4}$, $y = \\dfrac{5\\pi}{6}$, $z = \\dfrac{\\pi}{3}$", "$x = \\dfrac{\\pi}{4}$, $y = \\dfrac{7\\pi}{6}$, $z = \\dfrac{2\\pi}{3}$"]'::jsonb, 0, 'Row-reducing the augmented matrix of $a-2b=2$, $a-b+c=2$, $b-c=-1$ yields $c=\frac{1}{2}$, then $b=-\frac{1}{2}$ from $b+c=0$, then $a=1$ from $a-2b=2$. Since $\tan x = 1$ in the first interval, $x=\frac{\pi}{4}$; since $\sin y = -\frac{1}{2}$ in its interval, $y=\pi+\frac{\pi}{6}=\frac{7\pi}{6}$; since $\cos z = \frac{1}{2}$, $z=\frac{\pi}{3}$.', 'Solving a Nonlinear System via Substitution', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Using the Regula-Falsi (method of chords) iteration scheme, compute an appropriate real root of $x^2 + 4\sin x = 0$, correct to 3 significant figures.', '["$x \\approx -1.50$", "$x \\approx -1.86$", "$x \\approx -1.93$", "$x \\approx -2.00$"]'::jsonb, 2, 'Testing $f(x) = x^2+4\sin x$ at $x=-1$ and $x=-2$ shows $f(-1) < 0$ and $f(-2) > 0$, so a root lies in $[-2,-1]$. Applying the Regula-Falsi formula $x_2 = x_1 - \dfrac{x_1-x_0}{f(x_1)-f(x_0)}f(x_0)$ repeatedly, the iterates converge to approximately $-1.934$, which rounds to $-1.93$ to 3 significant figures.', 'Regula-Falsi Root-Finding Method', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'In a circuit with three unknown currents $I_1$, $I_2$, $I_3$ governed by $I_1 - I_2 + I_3 = 0$, $I_1 + I_2 = 8$, and $I_2 + 4I_3 = 13$, find $I_1$, $I_2$, and $I_3$.', '["$I_1 = 3$, $I_2 = 5$, $I_3 = 2$", "$I_1 = 5$, $I_2 = 3$, $I_3 = 2$", "$I_1 = 2$, $I_2 = 5$, $I_3 = 3$", "$I_1 = 3$, $I_2 = 2$, $I_3 = 5$"]'::jsonb, 0, 'Row-reducing the system''s augmented matrix using $I_1+I_2=8$ and $I_2+4I_3=13$ as the independent equations leads to $\frac{9}{2}I_3 = 9$, so $I_3 = 2$. Back-substituting, $I_2 - \frac{1}{2}(2) = 4 \Rightarrow I_2 = 5$, and then $I_1 - I_2 + I_3 = 0 \Rightarrow I_1 = I_2 - I_3 = 5 - 2 = 3$.', 'Solving a Linear System for Circuit Currents', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Obtain the optimal solution to the LP model: maximize $Z = 10x + y + 2z$ subject to $x + y - 2z \leq 10$, $4x + y + z \leq 20$, $x, y \geq 0$.', '["$x = 5, y = 0, z = 0$, $Z = 50$", "$x = 0, y = 0, z = 10$, $Z = 20$", "$x = 5, y = 0, z = 0$, $Z = 40$", "$x = 2, y = 0, z = 4$, $Z = 28$"]'::jsonb, 0, 'Introducing slack variables and running the simplex method on $x+y-2z+s_1=10$, $4x+y+z+s_2=20$ shows that increasing $x$ improves $Z$ fastest, and the second constraint becomes binding first. The simplex tableau converges to the optimal basic feasible solution $x=5$, $y=0$, $z=0$, which satisfies $4(5)=20\leq 20$ and gives $Z=10(5)+0+2(0)=50$.', 'Simplex Method for LP', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Using the Newton-Raphson method starting from $x_0 = 0.6$, find the approximate root of $20x^3 - 22x^2 + 5x - 1 = 0$, correct to 3 significant figures.', '["$x \\approx 0.898$", "$x \\approx 0.881$", "$x \\approx 1.168$", "$x \\approx 1.500$"]'::jsonb, 1, 'Applying $x_{n+1} = x_n - \dfrac{f(x_n)}{f''(x_n)}$ with $f(x)=20x^3-22x^2+5x-1$ and $x_0=0.6$, the iterates $0.6, 8.6, 5.859, \ldots$ eventually settle down and converge to approximately $0.8806$, which rounds to $0.881$ to 3 significant figures.', 'Newton-Raphson Iteration Scheme', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'The temperature on the sphere $x^2+y^2+z^2=1$ is given by $T(x,y,z) = 100xyz$. Using the method of Lagrange multipliers, find the greatest temperature attained on the sphere.', '["$T = \\dfrac{100}{3} \\approx 33.3^{\\circ}C$", "$T = \\dfrac{100\\sqrt{3}}{9} \\approx 19.245^{\\circ}C$", "$T = -\\dfrac{100\\sqrt{3}}{9} \\approx -19.245^{\\circ}C$", "$T = \\dfrac{100\\sqrt{3}}{3} \\approx 57.7^{\\circ}C$"]'::jsonb, 1, 'Setting $\nabla T = \lambda \nabla g$ with $g=x^2+y^2+z^2-1$ gives $yz=2\lambda x$, $xz=2\lambda y$, $xy=2\lambda z$, which combined with the constraint yields critical points at $x=y=z=\pm\frac{1}{\sqrt{3}}$ and points where one variable''s sign differs. Evaluating $T$ at these points, the greatest value occurs at $\left(\frac{1}{\sqrt{3}},\frac{1}{\sqrt{3}},\frac{1}{\sqrt{3}}\right)$ (and its all-negative counterpart), giving $T=\dfrac{100\sqrt{3}}{9}\approx19.245^{\circ}C$.', 'Lagrange Multipliers on a Constraint Surface', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For what value of $a$ does the system $x + 2y = 5$, $2x - ay = 4$ have no solution?', '["$a = 4$", "$a = -4$", "$a = -2$", "$a = 2$"]'::jsonb, 1, 'The system $\begin{pmatrix}1 & 2\\2 & -a\end{pmatrix}\begin{pmatrix}x\\y\end{pmatrix}=\begin{pmatrix}5\\4\end{pmatrix}$ has no solution when the coefficient determinant is zero (and the equations remain inconsistent): $\begin{vmatrix}1 & 2\\2 & -a\end{vmatrix} = -a - 4 = 0$, so $a=-4$. Note that $a=4$ does not make the determinant vanish, since $-4-4=-8\neq0$.', 'System of Linear Equations with a Parameter', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'If $A$ is a $3\times3$ matrix with $\det(A) = -2$, what is $\det\left(\dfrac{1}{2}A\right)$?', '["$-1$", "$-\\dfrac{1}{8}$", "$-\\dfrac{1}{4}$", "$\\dfrac{1}{4}$"]'::jsonb, 2, 'For an $n\times n$ matrix, scaling by a constant $\lambda$ scales the determinant by $\lambda^n$: $\det(\lambda A) = \lambda^n \det(A)$. Here $n=3$ and $\lambda=\frac{1}{2}$, so $\det\left(\frac{1}{2}A\right) = \left(\frac{1}{2}\right)^3(-2) = \frac{1}{8}\times(-2) = -\frac{1}{4}$.', 'Determinant Scaling Property', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Using Gauss elimination, solve the system $x + 2y - 3z = 1$, $2x - 3y + z = -5$, $3x - y + 4z = 2$.', '["$(x, y, z) = (0, 2, 1)$", "$(x, y, z) = (1, 2, 0)$", "$(x, y, z) = (0, 1, 2)$", "$(x, y, z) = (2, 0, 1)$"]'::jsonb, 0, 'Eliminating $x$ from the second and third equations using $E_2 \to -2E_1+E_2$ and $E_3 \to -3E_1+E_3$ gives $-7y+7z=-7$ and $-7y+13z=-1$. Eliminating $y$ next gives $6z=6$, so $z=1$; back-substituting gives $-7y+7=-7 \Rightarrow y=2$, and $x+2(2)-3(1)=1 \Rightarrow x=0$. So $(x,y,z)=(0,2,1)$.', 'Gauss Elimination Method', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'By reducing $A = \begin{pmatrix} 1 & 1 & 1 \\ 1 & 2 & 1 \\ 1 & 3 & -1 \end{pmatrix}$ to a triangular matrix, find $\det(A)$.', '["$\\det(A) = 2$", "$\\det(A) = -2$", "$\\det(A) = -6$", "$\\det(A) = 4$"]'::jsonb, 1, 'Applying $R_2 \to R_2 - R_1$ and $R_3 \to R_3 - R_1$ gives $\begin{pmatrix}1&1&1\\0&1&0\\0&2&-2\end{pmatrix}$, then $R_3 \to R_3 - 2R_2$ gives the upper triangular matrix $\begin{pmatrix}1&1&1\\0&1&0\\0&0&-2\end{pmatrix}$. Since row operations of this type (adding a multiple of one row to another) do not change the determinant, $\det(A)$ equals the product of the diagonal entries: $1 \times 1 \times (-2) = -2$.', 'Determinant via Triangularization', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Matrix $B$ is obtained from a matrix $A$ (with $\det(A) = -2$) by swapping two of its columns, so $\det(B) = 2$. Using the property $|\text{adj}(B)| = |B|^{n-1}$ for an $n \times n$ matrix, evaluate $|\text{adj}(B)|$ for this $3\times3$ matrix $B$.', '["$|\\text{adj}(B)| = 2$", "$|\\text{adj}(B)| = -4$", "$|\\text{adj}(B)| = 4$", "$|\\text{adj}(B)| = 8$"]'::jsonb, 2, 'Swapping two columns of a matrix negates its determinant, so $\det(B) = -\det(A) = -(-2) = 2$. For an $n\times n$ matrix, the identity $|\text{adj}(B)| = |B|^{n-1}$ holds; with $n=3$ and $|B|=2$, this gives $|\text{adj}(B)| = 2^{3-1} = 2^2 = 4$.', 'Determinant of the Adjugate Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Given the dual program: minimize $u = 10w_1 + 2w_2 + 6w_3$ subject to $4w_1 + 10w_2 - 4w_3 \geq -6$, $3w_1 - 6w_2 + 2w_3 \geq 4$, $w_1, w_2, w_3 \geq 0$, what is the corresponding primal (maximum) program?', '["Maximize $f = -6x_1 + 4x_2$ subject to $4x_1 + 3x_2 \\leq 10$, $10x_1 - 6x_2 \\leq 2$, $-4x_1 + 2x_2 \\leq 6$, $x_1, x_2 \\geq 0$", "Maximize $f = 10x_1 + 2x_2 + 6x_3$ subject to $4x_1 + 10x_2 - 4x_3 \\leq -6$, $3x_1 - 6x_2 + 2x_3 \\leq 4$, $x_1, x_2, x_3 \\geq 0$", "Maximize $f = -6x_1 + 4x_2$ subject to $4x_1 + 10x_2 \\leq 10$, $3x_1 - 6x_2 \\leq 2$, $2x_1 + x_2 \\leq 6$, $x_1, x_2 \\geq 0$", "Maximize $f = -6x_1 + 4x_2$ subject to $4x_1 + 3x_2 \\geq 10$, $10x_1 - 6x_2 \\geq 2$, $-4x_1 + 2x_2 \\geq 6$, $x_1, x_2 \\geq 0$"]'::jsonb, 0, 'The dual''s objective coefficients $(-6, 4)$ become the primal''s objective coefficients, and the dual''s constraint right-hand sides $(10, 2, 6)$ become the primal''s right-hand sides, with the constraint matrix transposed (each dual constraint''s coefficients become a primal constraint''s column) and the inequality direction flipped to $\leq$. This gives: maximize $f=-6x_1+4x_2$ subject to $4x_1+3x_2\leq10$, $10x_1-6x_2\leq2$, $-4x_1+2x_2\leq6$, $x_1,x_2\geq0$.', 'Dual of a Linear Programming Model', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Solving a linear program by the simplex method, the optimal primal solution is found to be $z_{max} = 13$ at $x_1 = \dfrac{1}{10}$ and $x_2 = \dfrac{16}{5}$. What are the corresponding dual variable values $w_1, w_2, w_3$ read from the optimal simplex tableau?', '["$w_1 = 0, w_2 = 1, w_3 = \\dfrac{1}{2}$", "$w_1 = 1, w_2 = 0, w_3 = \\dfrac{1}{2}$", "$w_1 = \\dfrac{1}{2}, w_2 = 0, w_3 = 1$", "$w_1 = 1, w_2 = \\dfrac{1}{2}, w_3 = 0$"]'::jsonb, 1, 'By the duality theorem, the optimal objective values of the primal and dual coincide, so $u_{min}=13$ as well. Reading the values of the slack/artificial variable columns in the final optimal simplex tableau (which give the dual variables) yields $w_1 = 1$, $w_2 = 0$, $w_3 = \dfrac{1}{2}$, and this triple can be verified to satisfy the dual''s constraints.', 'Reading Dual Values from an Optimal Simplex Tableau', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Maximize $f(x,y,z) = x^4 + y^4 + z^4$ subject to $x^2 + y^2 + z^2 = 3$, using the method of Lagrange multipliers.', '["Maximum value is $9$, at $(\\pm1, \\pm1, \\pm1)$", "Maximum value is $27$, at $(\\pm\\sqrt{3}, 0, 0)$", "Maximum value is $3$, at $(\\pm1, \\pm1, \\pm1)$", "Maximum value is $3\\sqrt{3}$, at $(\\pm1, \\pm1, \\pm1)$"]'::jsonb, 2, 'Setting $\nabla f = \lambda \nabla g$ with $g=x^2+y^2+z^2-3$ gives $4x^3=2\lambda x$, $4y^3=2\lambda y$, $4z^3=2\lambda z$, so $2x^2=2y^2=2z^2=\lambda$, meaning $x^2=y^2=z^2$. Substituting into the constraint gives $3x^2=3$, so $x=\pm1$, and similarly $y=\pm1$, $z=\pm1$. Evaluating $f$ at these points gives $f=1^4+1^4+1^4=3$, the maximum value.', 'Lagrange Multipliers on a Constraint Surface', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Given the matrix $A = \begin{pmatrix} 1 & 2 & 0 & 2 \\ -1 & 2 & 3 & 1 \\ -3 & 2 & -1 & 0 \\ 2 & -3 & -2 & 1 \end{pmatrix}$, reduce $A$ to triangular form using row operations and hence evaluate $|A|$.', '["$63$", "$-56$", "$-63$", "$-49$"]'::jsonb, 2, 'Applying row operations $R_2 \to R_2 + R_1$, $R_3 \to R_3 + 3R_1$, and further eliminating below the second pivot reduces $A$ to a lower triangular matrix with diagonal entries $1, 4, -7, \frac{9}{4}$. The determinant of a triangular matrix is the product of its diagonal entries, so $|A| = 1 \times 4 \times (-7) \times \frac{9}{4} = -63$.', 'Determinant by Row Reduction', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For what value(s) of $t$ is the matrix $A = \begin{pmatrix} 1 & t & 0 \\ 0 & 1 & -1 \\ t & 0 & 1 \end{pmatrix}$ singular?', '["$t = 0$", "$t = \\pm 2$", "$t = 1$ only", "$t = \\pm 1$"]'::jsonb, 3, 'Expanding along the first row, $|A| = 1(1 \times 1 - (-1) \times 0) - t(0 \times 1 - (-1) \times t) + 0 = 1 - t^2$. Setting $|A| = 0$ gives $1 - t^2 = 0$, so $t^2 = 1$, meaning $t = \pm 1$. At either value the matrix loses full rank and becomes singular.', 'Condition for a Singular Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Starting from $x_0 = 1$, apply the Newton-Raphson method to $f(x) = x^3 - 2$ to approximate its root, iterating with $x_{n+1} = x_n - \frac{2x_n^3+2}{3x_n^2}$ until the value stabilizes.', '["$1.3333$", "$1.2599$", "$1.2638$", "$1.1892$"]'::jsonb, 1, 'With $f(x) = x^3 - 2$ and $f''(x) = 3x^2$, the iteration formula simplifies to $x_{n+1} = \frac{2}{3x_n^2}(x_n^3+1)$. Starting from $x_0 = 1$ gives $x_1 = 1.3333$, then $x_2 = 1.2638$, then $x_3 = 1.2599$, which repeats on the next iteration. The root converges to $x = 1.2599$, matching $\sqrt[3]{2}$.', 'Newton-Raphson Iteration Scheme', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'A farmer wants to feed her stock at minimum cost using two feeds, costing \N30.00 and \N12.00 per kg respectively, subject to $3x_1+2x_2 \geq 60$, $7x_1+2x_2 \geq 84$, $3x_1+6x_2 \geq 72$, and $x_1,x_2 \geq 0$, minimizing $z = 30x_1+12x_2$. Using the graphical method, what is the optimal feed mixture and minimum cost?', '["$x_1=6,\\ x_2=21$, cost $=\\N432.00$", "$x_1=18,\\ x_2=4$, cost $=\\N588.00$", "$x_1=12,\\ x_2=6$, cost $=\\N408.00$", "$x_1=11,\\ x_2=7$, cost $=\\N414.00$"]'::jsonb, 3, 'The feasible region''s corner points are found by intersecting pairs of boundary lines: $(6,21)$, $(18,4)$, and $(11,7)$. Evaluating the cost at each: at $(6,21)$, $z=30(6)+12(21)=\N432$; at $(18,4)$, $z=30(18)+12(4)=\N588$; at $(11,7)$, $z=30(11)+12(7)=\N414$. The smallest of these is at $(11,7)$, so the optimal diet uses 11 kg and 7 kg of the two feeds at a total cost of \N414.00.', 'Linear Programming Diet Problem', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Use the method of Lagrange multipliers to maximize $f(x,y,z) = xyz$ subject to the constraint $x^3+y^3+z^3 = 1$, with $x,y,z \geq 0$.', '["$\\frac{1}{9}$", "$1$", "$\\frac{1}{3}$", "$3$"]'::jsonb, 2, 'With $g(x,y,z) = x^3+y^3+z^3-1$, the Lagrange condition $\nabla f = \lambda \nabla g$ gives $yz = \lambda 3x^2$, $xz = \lambda 3y^2$, $xy = \lambda 3z^2$. Multiplying each equation through by $x, y, z$ respectively and comparing shows $x^3=y^3=z^3$, so $x=y=z$. Substituting into the constraint gives $3x^3=1$, so $x=y=z=\left(\frac{1}{3}\right)^{1/3}$, and $f_{max} = xyz = \left(\frac{1}{3}\right)^{3/3} = \frac{1}{3}$.', 'Lagrange Multipliers', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Solve the linear program $\text{maximize } z = -3x_1 - x_2 + 9x_3$ subject to $6x_1-3x_2-3x_3 \leq 3$, $-3x_1+6x_2+3x_3 \leq 6$, $-7x_1+8x_2+6x_3 \leq 21$, $x_1,x_2,x_3 \geq 0$ using the simplex method.', '["$z_{max}=36$ at $x_1=0,\\ x_2=3,\\ x_3=5$", "$z_{max}=30$ at $x_1=3,\\ x_2=5,\\ x_3=0$", "$z_{max}=36$ at $x_1=3,\\ x_2=0,\\ x_3=5$", "$z_{max}=34$ at $x_1=5,\\ x_2=0,\\ x_3=3$"]'::jsonb, 2, 'Introducing slack variables $s_1,s_2,s_3$ and pivoting through the simplex tableau drives $x_2$ and the slacks associated with the first two constraints out of the basis, leaving $x_1$ and $x_3$ basic. The optimal tableau gives $x_1=3,\ x_2=0,\ x_3=5$. Checking feasibility: $6(3)-3(0)-3(5)=3$ and $-3(3)+6(0)+3(5)=6$, both binding, while the third constraint has slack. The objective value is $z=-3(3)-0+9(5)=36$.', 'Simplex Method', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For what value of $a$ does the system $x+3y=4$, $2x+6y=a$ have infinitely many solutions (i.e. remain consistent)?', '["$a=8$", "$a=4$", "$a=12$", "$a=0$"]'::jsonb, 0, 'Subtracting twice the first equation from the second gives $2x+6y - 2(x+3y) = a - 2(4)$, which simplifies to $0 = a-8$. The system is consistent (and has infinitely many solutions, since the two equations become identical) only when $a-8=0$, that is, $a=8$.', 'Consistency of a Linear System', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Use Cramer''s rule to solve the system $x+y+z=2$, $x+2y+z=2$, $x+2y-z=4$ for $(x,y,z)$.', '["$(0,3,-1)$", "$(3,-1,0)$", "$(-1,0,3)$", "$(3,0,-1)$"]'::jsonb, 3, 'The coefficient determinant is $|A| = 1(2(-1)-1(2)) - 1(1(-1)-1(1)) + 1(1(2)-2(1)) = -4+2+0 = -2$. Replacing the first column with the constants $(2,2,4)$ gives $|A_1|=-6$, so $x=\frac{-6}{-2}=3$. Replacing the second column gives $|A_2|=0$, so $y=0$, and replacing the third column gives $|A_3|=2$, so $z=\frac{2}{-2}=-1$. Hence $(x,y,z)=(3,0,-1)$.', 'Cramer''s Rule', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Starting from $x_1 = 0.5$ radians, use the Newton-Raphson method to solve $2\sin x - \cos x = 0$, giving your answer correct to 3 decimal places.', '["$0.500$", "$0.496$", "$0.464$", "$0.436$"]'::jsonb, 2, 'With $f(x)=2\sin x - \cos x$ and $f''(x)=2\cos x + \sin x$, the iteration $x_{n+1}=x_n - \frac{f(x_n)}{f''(x_n)}$ starting at $x_1=0.5$ produces $x_2 \approx 0.496$, then $x_3 \approx 0.464$, then $x_4 \approx 0.464$, so the iteration has converged. The root correct to 3 decimal places is $x \approx 0.464$.', 'Newton-Raphson Iteration Scheme', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Find $|A|$ for $A = \begin{pmatrix} 1 & 2 & 1 \\ 0 & 1 & 3 \\ 2 & 1 & 1 \end{pmatrix}$ by first reducing it to triangular form.', '["$-8$", "$6$", "$8$", "$12$"]'::jsonb, 2, 'Applying $R_3 \to R_3 - 2R_1$ gives $\begin{pmatrix} 1 & 2 & 1 \\ 0 & 1 & 3 \\ 0 & -3 & -1 \end{pmatrix}$, then $R_3 \to R_3 + 3R_2$ gives the upper triangular matrix $\begin{pmatrix} 1 & 2 & 1 \\ 0 & 1 & 3 \\ 0 & 0 & 8 \end{pmatrix}$. The determinant is the product of the diagonal entries, $1 \times 1 \times 8 = 8$.', 'Determinant by Row Reduction', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Which of the following pairs of linear equations has infinitely many solutions?', '["$x_1+x_2=2,\\ x_1-x_2=-2$", "$x_1+x_2=2,\\ x_1+x_2=1$", "$x_1+x_2=3,\\ x_1-x_2=2$", "$x_1+x_2=2,\\ 3x_1+3x_2=6$"]'::jsonb, 3, 'For a $2\times 2$ system to have infinitely many solutions, the two equations must be scalar multiples of each other. In the last pair, multiplying $x_1+x_2=2$ by 3 gives exactly $3x_1+3x_2=6$, so the two equations describe the same line and every point on it is a solution. The other pairs either have nonzero coefficient determinants (unique solution) or contradictory right-hand sides (no solution).', 'Classifying Linear Systems', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Which of the following pairs of linear equations is inconsistent (has no solution)?', '["$x_1+x_2=4,\\ x_1+x_2=5$", "$2x_1+2x_2=4,\\ x_1+x_2=2$", "$x_1+x_2=3,\\ x_1-x_2=1$", "$x_1+x_2=2,\\ x_1-x_2=4$"]'::jsonb, 0, 'The first pair has identical left-hand sides, $x_1+x_2$, but different right-hand sides, 4 and 5, which is a direct contradiction, so no values of $x_1,x_2$ can satisfy both equations. The second pair is really the same equation twice (infinitely many solutions), while the third and fourth pairs each have a nonzero coefficient determinant and so have a unique solution.', 'Classifying Linear Systems', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Which of the following pairs of linear equations has a unique solution?', '["$x_1+x_2=2,\\ 2x_1+2x_2=4$", "$x_1+x_2=2,\\ x_1+x_2=1$", "$x_1+x_2=2,\\ x_1-x_2=4$", "$x_1+x_2=1,\\ 3x_1+3x_2=3$"]'::jsonb, 2, 'For the pair $x_1+x_2=2$ and $x_1-x_2=4$, the coefficient determinant is $\begin{vmatrix} 1 & 1 \\ 1 & -1 \end{vmatrix} = -1-1 = -2 \neq 0$, so this system has exactly one solution, namely $x_1=3,\ x_2=-1$. The other pairs are either scalar multiples of each other (infinitely many solutions) or contradictory (no solution).', 'Classifying Linear Systems', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Which of the following intervals does NOT contain a root of $f(x) = 2x^3+3x^2-12x+2$?', '["$(-4,-3)$", "$(0,1)$", "$(1,2)$", "$(3,4)$"]'::jsonb, 3, 'Evaluating $f$ at integer points gives $f(-4)=-30$, $f(-3)=11$, $f(0)=2$, $f(1)=-5$, $f(2)=6$, $f(3)=47$, $f(4)=130$. A sign change between consecutive values guarantees a root in that interval, which happens for $(-4,-3)$, $(0,1)$, and $(1,2)$. Since $f(3)=47$ and $f(4)=130$ are both positive, there is no sign change and hence no guaranteed root in $(3,4)$.', 'Root Separation Interval', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Given the upper triangular matrix $A = \begin{pmatrix} 1 & 2 & -3 \\ 0 & 5 & 1 \\ 0 & 0 & 2 \end{pmatrix}$, find $|A|$.', '["$10$", "$-10$", "$8$", "$-2$"]'::jsonb, 0, 'For a triangular matrix, the determinant is simply the product of the diagonal entries. Here the diagonal is $1, 5, 2$, so $|A| = 1 \times 5 \times 2 = 10$.', 'Determinant of a Triangular Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the matrix $A = \begin{pmatrix} 1 & 2 & -3 \\ 0 & 5 & 1 \\ 0 & 0 & 2 \end{pmatrix}$ with $|A|=10$, find $|\text{adj}\,A|$.', '["$10$", "$100$", "$-10$", "$1000$"]'::jsonb, 1, 'For an $n \times n$ matrix, the identity $|\text{adj}\,A| = |A|^{n-1}$ holds. Here $A$ is $3 \times 3$, so $n-1=2$, giving $|\text{adj}\,A| = |A|^2 = 10^2 = 100$.', 'Determinant of the Adjugate Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the matrix $A = \begin{pmatrix} 1 & 2 & -3 \\ 0 & 5 & 1 \\ 0 & 0 & 2 \end{pmatrix}$ with $|A|=10$, find $|A^{-1}|$.', '["$10$", "$-10$", "$\\frac{1}{10}$", "$-\\frac{1}{10}$"]'::jsonb, 2, 'Since $A A^{-1} = I$, taking determinants gives $|A||A^{-1}|=1$, so $|A^{-1}| = \frac{1}{|A|}$. With $|A|=10$, this gives $|A^{-1}| = \frac{1}{10}$.', 'Determinant of the Inverse Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Let $A = \begin{pmatrix} 1 & 2 & -3 \\ 0 & 5 & 1 \\ 0 & 0 & 2 \end{pmatrix}$ with $|A|=10$, and let $B$ be the matrix obtained from $A$ by swapping the first and second rows. Find $|B|$.', '["$10$", "$-10$", "$20$", "$5$"]'::jsonb, 1, 'Swapping any two rows of a matrix reverses the sign of its determinant while leaving its magnitude unchanged. Since $|A| = 10$, swapping rows 1 and 2 gives $B = \begin{pmatrix} 0 & 5 & 1 \\ 1 & 2 & -3 \\ 0 & 0 & 2 \end{pmatrix}$ with $|B| = -|A| = -10$.', 'Effect of Row Operations on a Determinant', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Use Lagrange multipliers to find the maximum value of $F(x,y) = xy$ on the circle $x^2+y^2=1$.', '["$\\frac{1}{2}$", "$1$", "$\\sqrt{2}$", "$-\\frac{1}{2}$"]'::jsonb, 0, 'With $g(x,y)=x^2+y^2-1$, the Lagrange condition $\nabla F = \lambda \nabla g$ gives $y=2\lambda x$ and $x=2\lambda y$. Substituting one into the other gives $4\lambda^2=1$, so $\lambda = \pm\frac{1}{2}$, and correspondingly $y = \pm x$. On the circle, taking $y=x$ gives $2x^2=1$, so $x=y=\frac{1}{\sqrt{2}}$, and the maximum value is $F = xy = \frac{1}{\sqrt{2}} \times \frac{1}{\sqrt{2}} = \frac{1}{2}$ (the case $y=-x$ gives the minimum, $-\frac{1}{2}$).', 'Lagrange Multipliers on a Circle', false, 'second', 2);
